public boolean hasModifications(TFMDataSourceBlock _blockToModify)
{
    TableName tn = _blockToModify.getDataSource().TableName;
    TFMOrderTypes orderType = _blockToModify.getDataSource().OrderType;

    return tn == tableStr(WMSJournalTrans) ||                
           tn == tableStr(ITMLine) ||
           tn == tableStr(PurchLine) ||
           (tn == tableStr(InventTransferLine) && orderType == MobConstants::Receive());

}

public void modifyValuesBeforeDelta(TFMDataSourceBlock _blockToModify, Common _common =null)
{
    TFMDataSourceBlockOrderLineItemSetup itemSetup = _blockToModify as TFMDataSourceBlockOrderLineItemSetup;
    if (_common.TableId == tableNum(PurchLine))
    {
        PurchLine purchLine = _common as PurchLine;
        if (purchLine.PurchQty < 0)
        {
            return;
        }
    }

    if (_common.TableId == tableNum(InventTransferLine))
    {
        InventTransferLine      inventTransferLine = _common as InventTransferLine;
        itemSetup.setOverrideInventTransId(inventTransferLine.InventTransIdReceive);
        itemSetup.setOverrideInventDimId(inventTransferLine.inventDimReceive().inventDimId);
    }


    itemSetup.parmActionType(TFMActionTypes::PLACE);
}
